                                                            canonicalDirName,
                                                            dirname,
                                                            testname,
                                                            failsOnly,
                                                            expect_not_passing,
                                                            shouldFail));
    for (String c : new ArrayList<String>(java.util.Arrays.asList(supported))) {
        if (props.get(c) != null) found = true;
    }
    if (!found) {
        throw new IllegalArgumentException("No supported tests found in " +
                                           dirname + "/" + testname);
    }
}

